      "jawab": 1,
      "konteks": "Bila puluhannya sama, bandingkan satuannya. Tanda < dan > membuka ke bilangan yang lebih besar, seperti mulut yang ingin \"makan\" yang banyak. Ajak anak menaruh 44 dan 48 kelereng berdampingan: mana yang lebih banyak, dan mana yang lebih sedikit? Lalu pilih kalimat yang cocok.",
