      "konteks": "Prisma punya dua sisi yang bentuknya sama (alas dan tutup) dan sisi-sisi samping yang berbentuk persegi panjang. Pada gambar, perhatikan bentuk sisi depannya: itulah yang memberi nama prisma. Contoh benda sehari-hari: kotak cokelat segitiga atau atap rumah berbentuk pelana.",
