      "jawab": 1,
      "konteks": "Gerak berirama dilakukan bersama-sama mengikuti musik yang sama, sehingga gerakan terlihat serempak. Ajak anak dan anggota keluarga lain bergerak dengan lagu yang sama, lalu bandingkan dengan saat setiap orang bergerak sendiri-sendiri. Anak akan melihat sendiri mana yang tampak kompak.",
