      "konteks": "Berjalan mundur adalah berjalan ke arah belakang, dan ini termasuk gerak lokomotor. Ajak anak berjalan maju lalu berjalan ke arah sebaliknya di tempat aman, lalu tanyakan namanya. Panah pada gambar menunjuk ke arah belakang.",
