      "konteks": "Merangkak adalah gerak lokomotor, karena badan berpindah tempat dengan bertumpu pada tangan dan lutut. Tunjukkan gambar, lalu ajak anak mengingat cara adik bayi atau sepupunya bergerak sebelum bisa berjalan.",
