      "konteks": "Saat berdiri satu kaki badan mudah goyang, sehingga tangan direntangkan untuk membantu menjaga keseimbangan. Ajak anak mencoba berdiri satu kaki dengan tangan di bawah dan dengan tangan terentang, lalu tanyakan mana yang lebih stabil. Jawabannya adalah nama dari keadaan stabil itu.",
