      "konteks": "Setelah berolahraga, badan berkeringat dan mudah berbau. Mandi dan berganti pakaian bersih adalah kebiasaan hidup sehat. Tanyakan kepada anak apa yang biasa ia lakukan sepulang bermain di luar agar badannya bersih dan segar.",
