      "konteks": "Membasahi tubuh adalah gerak dasar aktivitas air yang dilakukan sebelum masuk kolam, dimulai dari kaki lalu tangan dan dada, agar badan tidak kaget. Peragakan dengan gayung di kamar mandi, lalu tanyakan kata kerja untuk membuat tubuh menjadi basah. Kata itu berawalan \"mem-\".",
