      "konteks": "Tolong-menolong berarti saling membantu. Tanyakan kepada anak apa yang ia rasakan jika ada teman yang membantunya saat ia kesulitan. Lalu minta ia menyebutkan nama sikap Budi yang dalam Islam juga dianjurkan.",
      "kisi": "PJ5",
