      "konteks": "Salat adalah kewajiban yang dikerjakan pada waktunya masing-masing: Subuh, Zuhur, Asar, Magrib, dan Isya. Ingatkan anak bahwa olahraga atau bermain tidak boleh membuat kita menunda salat. Frasa \"tepat ...\" sering dipakai dalam kalimat sehari-hari, misalnya \"tepat ... datang ke sekolah\".",
