      "tanya": "Bukumu tidak ada di tasmu. Kamu ingin bertanya kepada Bu Guru dengan sopan. Tulis kalimat yang kamu ucapkan (boleh bahasa Inggris atau Indonesia). Lalu, apa yang kamu ucapkan setelah Bu Guru membantu?",
